"1320 :   private NameInformation createNameInformation(NodeTraversal t, Node n,
1321 :       Node parent) {
1322 :     // Build the full name and find its root node by iterating down through all
1323 :     // GETPROP/GETELEM nodes.
1324 :     String name = "";
1325 :     Node rootNameNode = n;
1326 :     boolean bNameWasShortened = false;
1327 :     while (true) {
1328 :       if (NodeUtil.isGet(rootNameNode)) {
1329 :         Node prop = rootNameNode.getLastChild();
1330 :         if (rootNameNode.isGetProp()) {
1331 :           name = "." + prop.getString() + name;
1332 :         } else {
1333 :           // We consider the name to be "a.b" in a.b['c'] or a.b[x].d.
1334 :           bNameWasShortened = true;
1335 :           name = "";
1336 :         }
1337 :         rootNameNode = rootNameNode.getFirstChild();
1338 :       } else if (NodeUtil.isObjectLitKey(
1339 :           rootNameNode, rootNameNode.getParent())) {
1340 :         name = "." + rootNameNode.getString() + name;
1341 : 
1342 :         // Check if this is an object literal assigned to something.
1343 :         Node objLit = rootNameNode.getParent();
1344 :         Node objLitParent = objLit.getParent();
1345 :         if (objLitParent.isAssign()) {
1346 :           // This must be the right side of the assign.
1347 :           rootNameNode = objLitParent.getFirstChild();
1348 :         } else if (objLitParent.isName()) {
1349 :           // This must be a VAR initialization.
1350 :           rootNameNode = objLitParent;
1351 :         } else if (objLitParent.isString()) {
1352 :           // This must be a object literal key initialization.
1353 :           rootNameNode = objLitParent;
1354 :         } else {
1355 :           return null;
1356 :         }
1357 :       } else {
1358 :         break;
1359 :       }
1360 :     }
1361 : 
1362 :     // Check whether this is a class-defining call. Classes may only be defined
1363 :     // in the global scope.
1364 :     if (parent.isCall() && t.inGlobalScope()) {
1365 :       CodingConvention convention = compiler.getCodingConvention();
1366 :       SubclassRelationship classes = convention.getClassesDefinedByCall(parent);
1367 :       if (classes != null) {
1368 :         NameInformation nameInfo = new NameInformation();
1369 :         nameInfo.name = classes.subclassName;
1370 :         nameInfo.onlyAffectsClassDef = true;
1371 :         nameInfo.superclass = classes.superclassName;
1372 :         return nameInfo;
1373 :       }
1374 : 
1375 :       String singletonGetterClass =
1376 :           convention.getSingletonGetterClassName(parent);
1377 :       if (singletonGetterClass != null) {
1378 :         NameInformation nameInfo = new NameInformation();
1379 :         nameInfo.name = singletonGetterClass;
1380 :         nameInfo.onlyAffectsClassDef = true;
1381 :         return nameInfo;
1382 :       }
1383 :     }
1384 : 
1385 :     switch (rootNameNode.getType()) {
1386 :       case Token.NAME:
1387 :         // Check whether this is an assignment to a prototype property
1388 :         // of an object defined in the global scope.
1389 :         if (!bNameWasShortened &&
1390 :             n.isGetProp() &&
1391 :             parent.isAssign() &&
1392 :             "prototype".equals(n.getLastChild().getString())) {
1393 :           if (createNameInformation(t, n.getFirstChild(), n) != null) {
1394 :             name = rootNameNode.getString() + name;
1395 :             name = name.substring(0, name.length() - PROTOTYPE_SUFFIX_LEN);
1396 :             NameInformation nameInfo = new NameInformation();
1397 :             nameInfo.name = name;
1398 :             return nameInfo;
1399 :           } else {
1400 :             return null;
1401 :           }
1402 :         }
1403 :         return createNameInformation(
1404 :             rootNameNode.getString() + name, t.getScope(), rootNameNode);
1405 :       case Token.THIS:
1406 :         if (t.inGlobalScope()) {
1407 :           NameInformation nameInfo = new NameInformation();
1408 :           if (name.indexOf('.') == 0) {
1409 :             nameInfo.name = name.substring(1);  // strip leading "."
1410 :           } else {
1411 :             nameInfo.name = name;
1412 :           }
1413 :           nameInfo.isExternallyReferenceable = true;
1414 :           return nameInfo;
1415 :         }
1416 :         return null;
1417 :       default:
1418 :         return null;
1419 :     }
1420 :   }"

"817 :     @Override
818 :     public void visit(NodeTraversal t, Node n, Node parent) {
819 :       if (!(n.isName() ||
820 :             NodeUtil.isGet(n) && !parent.isGetProp())) {
821 :         // This is not a simple or qualified name.
822 :         return;
823 :       }
824 : 
825 :       NameInformation nameInfo = createNameInformation(t, n, parent);
826 :       if (nameInfo == null) {
827 :         // The name is not a global name
828 :         return;
829 :       }
830 : 
831 :       if (nameInfo.onlyAffectsClassDef) {
832 :         if (nameInfo.superclass != null) {
833 :           recordReference(
834 :               nameInfo.name, nameInfo.superclass, RefType.INHERITANCE);
835 :         }
836 : 
837 :         // Make sure that we record a reference to the function that does
838 :         // the inheritance, so that the inherits() function itself does
839 :         // not get stripped.
840 :         String nodeName = n.getQualifiedName();
841 :         if (nodeName != null) {
842 :           recordReference(
843 :               nameInfo.name, nodeName, RefType.REGULAR);
844 :         }
845 : 
846 :         return;
847 :       }
848 : 
849 :       if (parent.isInstanceOf() &&
850 :           parent.getLastChild() == n &&
851 :           // Don't cover GETELEMs with a global root node.
852 :           n.isQualifiedName()) {
853 :         JsName checkedClass = getName(nameInfo.name, true);
854 :         refNodes.add(
855 :             new InstanceOfCheckNode(
856 :                 checkedClass, n, parent, parent.getParent()));
857 :         checkedClass.hasInstanceOfReference = true;
858 :         return;
859 :       }
860 : 
861 :       // Determine which name might be potentially referring to this one by
862 :       // looking up the nearest enclosing dependency scope. It's unnecessary to
863 :       // determine all enclosing dependency scopes because this callback should
864 :       // create a chain of references between them.
865 :       NameInformation referring = getDependencyScope(n);
866 :       String referringName = "";
867 :       if (referring != null) {
868 :         referringName = referring.isPrototype
869 :                       ? referring.prototypeClass
870 :                       : referring.name;
871 :       }
872 : 
873 :       String name = nameInfo.name;
874 : 
875 :       // A value whose result is the return value of a function call
876 :       // can be an alias to global object.
877 :       // Here we add a alias to the general "global" object
878 :       // to act as a placeholder for the actual (unnamed) value.
879 :       if (maybeHiddenAlias(name, n)) {
880 :         recordAlias(name, WINDOW);
881 :       }
882 : 
883 :       // An externally referenceable name must always be defined, so we add a
884 :       // reference to it from the global scope (a.k.a. window).
885 :       if (nameInfo.isExternallyReferenceable) {
886 :         recordReference(WINDOW, name, RefType.REGULAR);
887 :         maybeRecordAlias(name, parent, referring, referringName);
888 :         return;
889 :       }
890 : 
891 :       // An assignment implies a reference from the enclosing dependency scope.
892 :       // For example, foo references bar in: function foo() {bar=5}.
893 :       if (NodeUtil.isVarOrSimpleAssignLhs(n, parent)) {
894 :         if (referring != null) {
895 :           recordReference(referringName, name, RefType.REGULAR);
896 :         }
897 :         return;
898 :       }
899 : 
900 :       if (nodesToKeep.contains(n)) {
901 :         NameInformation functionScope = getEnclosingFunctionDependencyScope(t);
902 :         if (functionScope != null) {
903 :           recordReference(functionScope.name, name, RefType.REGULAR);
904 :         } else {
905 :           recordReference(WINDOW, name, RefType.REGULAR);
906 :         }
907 :       } else if (referring != null) {
908 :         if (!maybeRecordAlias(name, parent, referring, referringName)) {
909 :           RefType depType = referring.onlyAffectsClassDef ?
910 :               RefType.INHERITANCE : RefType.REGULAR;
911 :           recordReference(referringName, name, depType);
912 :         }
913 :       } else {
914 :         // No named dependency scope found.  Unfortunately that might
915 :         // mean that the expression is a child of an function expression
916 :         // or assignment with a complex lhs.  In those cases,
917 :         // protect this node by creating a reference to WINDOW.
918 :         for (Node ancestor : n.getAncestors()) {
919 :           if (NodeUtil.isAssignmentOp(ancestor) ||
920 :               ancestor.isFunction()) {
921 :             recordReference(WINDOW, name, RefType.REGULAR);
922 :             break;
923 :           }
924 :         }
925 :       }
926 :     }"

"643 :     void handleGet(NodeTraversal t, Node n, Node parent, String name) {
644 :       if (maybeHandlePrototypePrefix(t, n, parent, name)) return;
645 : 
646 :       Ref.Type type = Ref.Type.DIRECT_GET;
647 :       if (parent != null) {
648 :         switch (parent.getType()) {
649 :           case Token.IF:
650 :           case Token.TYPEOF:
651 :           case Token.VOID:
652 :           case Token.NOT:
653 :           case Token.BITNOT:
654 :           case Token.POS:
655 :           case Token.NEG:
656 :             break;
657 :           case Token.CALL:
658 :             type = n == parent.getFirstChild()
659 :                    ? Ref.Type.CALL_GET
660 :                    : Ref.Type.ALIASING_GET;
661 :             break;
662 :           case Token.NEW:
663 :             type = n == parent.getFirstChild()
664 :                    ? Ref.Type.DIRECT_GET
665 :                    : Ref.Type.ALIASING_GET;
666 :             break;
667 :           case Token.OR:
668 :           case Token.AND:
669 :             // This node is x or y in (x||y) or (x&&y). We only know that an
670 :             // alias is not getting created for this name if the result is used
671 :             // in a boolean context or assigned to the same name
672 :             // (e.g. var a = a || {}).
673 :             type = determineGetTypeForHookOrBooleanExpr(t, parent, name);
674 :             break;
675 :           case Token.HOOK:
676 :             if (n != parent.getFirstChild()) {
677 :               // This node is y or z in (x?y:z). We only know that an alias is
678 :               // not getting created for this name if the result is assigned to
679 :               // the same name (e.g. var a = a ? a : {}).
680 :               type = determineGetTypeForHookOrBooleanExpr(t, parent, name);
681 :             }
682 :             break;
683 :           case Token.DELPROP:
684 :             type = Ref.Type.DELETE_PROP;
685 :             break;
686 :           default:
687 :             type = Ref.Type.ALIASING_GET;
688 :             break;
689 :         }
690 :       }
691 : 
692 :       handleGet(t, n, parent, name, type);
693 :     }"

"1432 :   private NameInformation createNameInformation(
1433 :       String name, Scope scope, Node rootNameNode) {
1434 :     // Check the scope. Currently we're only looking at globally scoped vars.
1435 :     String rootName = rootNameNode.getString();
1436 :     Var v = scope.getVar(rootName);
1437 :     boolean isExtern = (v == null && externalNames.contains(rootName));
1438 :     boolean isGlobalRef = (v != null && v.isGlobal()) || isExtern ||
1439 :         rootName.equals(WINDOW);
1440 :     if (!isGlobalRef) {
1441 :       return null;
1442 :     }
1443 : 
1444 :     NameInformation nameInfo = new NameInformation();
1445 : 
1446 :     // If a prototype property or method, fill in prototype information.
1447 :     int idx = name.indexOf(PROTOTYPE_SUBSTRING);
1448 :     if (idx != -1) {
1449 :       nameInfo.isPrototype = true;
1450 :       nameInfo.prototypeClass = name.substring(0, idx);
1451 :       nameInfo.prototypeProperty = name.substring(
1452 :           idx + PROTOTYPE_SUBSTRING_LEN);
1453 :     }
1454 : 
1455 :     nameInfo.name = name;
1456 :     nameInfo.isExternallyReferenceable =
1457 :         isExtern || isExternallyReferenceable(scope, name);
1458 :     return nameInfo;
1459 :   }"

"1094 :   private void recordReference(String fromName, String toName,
1095 :                                RefType depType) {
1096 :     if (fromName.equals(toName)) {
1097 :       // Don't bother recording self-references.
1098 :       return;
1099 :     }
1100 : 
1101 :     JsName from = getName(fromName, true);
1102 :     JsName to = getName(toName, true);
1103 :     referenceGraph.createNode(from);
1104 :     referenceGraph.createNode(to);
1105 :     if (!referenceGraph.isConnectedInDirection(from, depType, to)) {
1106 :       referenceGraph.connect(from, depType, to);
1107 :     }
1108 :   }"

"1030 :   @Override
1031 :   public void process(Node externs, Node root) {
1032 :     NodeTraversal.traverse(compiler, externs, new ProcessExternals());
1033 :     NodeTraversal.traverse(compiler, root, new FindDependencyScopes());
1034 :     NodeTraversal.traverse(
1035 :         compiler, root, new HoistVariableAndFunctionDeclarations());
1036 :     NodeTraversal.traverse(compiler, root, new FindDeclarationsAndSetters());
1037 :     NodeTraversal.traverse(compiler, root, new FindReferences());
1038 : 
1039 :     // Create bi-directional references between parent names and their
1040 :     // descendents. This may create new names.
1041 :     referenceParentNames();
1042 : 
1043 :     // If we modify the property of an alias, make sure that modification
1044 :     // gets reflected in the original object.
1045 :     referenceAliases();
1046 : 
1047 :     calculateReferences();
1048 : 
1049 :     if (removeUnreferenced) {
1050 :       removeUnreferenced();
1051 :     }
1052 :   }"

