"595 :     @Override
596 :     public void visit(NodeTraversal t, Node n, Node parent) {
597 : 
598 :       // Record global variable and function declarations
599 :       if (t.inGlobalScope()) {
600 :         if (NodeUtil.isVarDeclaration(n)) {
601 :           NameInformation ns = createNameInformation(t, n, parent);
602 :           Preconditions.checkNotNull(ns);
603 :           recordSet(ns.name, n);
604 :         } else if (NodeUtil.isFunctionDeclaration(n)) {
605 :           Node nameNode = n.getFirstChild();
606 :           NameInformation ns = createNameInformation(t, nameNode, n);
607 :           if (ns != null) {
608 :             JsName nameInfo = getName(nameNode.getString(), true);
609 :             recordSet(nameInfo.name, nameNode);
610 :           }
611 :         } else if (NodeUtil.isObjectLitKey(n, parent)) {
612 :           NameInformation ns = createNameInformation(t, n, parent);
613 :           if (ns != null) {
614 :             recordSet(ns.name, n);
615 :           }
616 :         }
617 :       }
618 : 
619 :       // Record assignments and call sites
620 :       if (n.isAssign()) {
621 :         Node nameNode = n.getFirstChild();
622 : 
623 :         NameInformation ns = createNameInformation(t, nameNode, n);
624 :         if (ns != null) {
625 :           if (ns.isPrototype) {
626 :             recordPrototypeSet(ns.prototypeClass, ns.prototypeProperty, n);
627 :           } else {
628 :             recordSet(ns.name, nameNode);
629 :           }
630 :         }
631 :       } else if (n.isCall()) {
632 :         Node nameNode = n.getFirstChild();
633 :         NameInformation ns = createNameInformation(t, nameNode, n);
634 :         if (ns != null && ns.onlyAffectsClassDef) {
635 :           JsName name = getName(ns.name, false);
636 :           if (name != null) {
637 :           refNodes.add(new ClassDefiningFunctionNode(
638 :               name, n, parent, parent.getParent()));
639 :           }
640 :         }
641 :       }
642 :     }"

"651 :     private void recordSet(String name, Node node) {
652 :       JsName jsn = getName(name, true);
653 :       JsNameRefNode nameRefNode = new JsNameRefNode(jsn, node);
654 :       refNodes.add(nameRefNode);
655 : 
656 :       // Now, look at all parent names and record that their properties have
657 :       // been written to.
658 :       if (node.isGetElem()) {
659 :         recordWriteOnProperties(name);
660 :       } else if (name.indexOf('.') != -1) {
661 :         recordWriteOnProperties(name.substring(0, name.lastIndexOf('.')));
662 :       }
663 :     }"

"684 :     private void recordWriteOnProperties(String parentName) {
685 :       do {
686 :         JsName parent = getName(parentName, true);
687 :         if (parent.hasWrittenDescendants) {
688 :           // If we already recorded this name, then all its parents must
689 :           // also be recorded. short-circuit this loop.
690 :           return;
691 :         } else {
692 :           parent.hasWrittenDescendants = true;
693 :         }
694 : 
695 :         if (parentName.indexOf('.') == -1) {
696 :           return;
697 :         }
698 :         parentName = parentName.substring(0, parentName.lastIndexOf('.'));
699 :       } while(true);
700 :     }"

"310 :     @Override
311 :     public void remove() {
312 :       // Setters have VAR, FUNCTION, or ASSIGN parent nodes. CALL parent
313 :       // nodes are global refs, and are handled later in this function.
314 :       Node containingNode = parent.getParent();
315 :       switch (parent.getType()) {
316 :         case Token.VAR:
317 :           Preconditions.checkState(parent.hasOneChild());
318 :           replaceWithRhs(containingNode, parent);
319 :           break;
320 :         case Token.FUNCTION:
321 :           replaceWithRhs(containingNode, parent);
322 :           break;
323 :         case Token.ASSIGN:
324 :           if (containingNode.isExprResult()) {
325 :             replaceWithRhs(containingNode.getParent(), containingNode);
326 :           } else {
327 :             replaceWithRhs(containingNode, parent);
328 :           }
329 :           break;
330 :         case Token.OBJECTLIT:
331 :           // TODO(nicksantos): Come up with a way to remove this.
332 :           // If we remove object lit keys, then we will need to also
333 :           // create dependency scopes for them.
334 :           break;
335 :       }
336 :     }"

"1620 :   private void replaceWithRhs(Node parent, Node n) {
1621 :     if (valueConsumedByParent(n, parent)) {
1622 :       // parent reads from n directly; replace it with n's rhs + lhs
1623 :       // subexpressions with side effects.
1624 :       List<Node> replacements = getRhsSubexpressions(n);
1625 :       List<Node> newReplacements = Lists.newArrayList();
1626 :       for (int i = 0; i < replacements.size() - 1; i++) {
1627 :         newReplacements.addAll(getSideEffectNodes(replacements.get(i)));
1628 :       }
1629 :       Node valueExpr = replacements.get(replacements.size() - 1);
1630 :       valueExpr.detachFromParent();
1631 :       newReplacements.add(valueExpr);
1632 :       changeProxy.replaceWith(
1633 :           parent, n, collapseReplacements(newReplacements));
1634 :     } else if (n.isAssign() && !parent.isFor()) {
1635 :       // assignment appears in a RHS expression.  we have already
1636 :       // considered names in the assignment's RHS as being referenced;
1637 :       // replace the assignment with its RHS.
1638 :       // TODO(user) make the pass smarter about these cases and/or run
1639 :       // this pass and RemoveConstantExpressions together in a loop.
1640 :       Node replacement = n.getLastChild();
1641 :       replacement.detachFromParent();
1642 :       changeProxy.replaceWith(parent, n, replacement);
1643 :     } else {
1644 :       replaceTopLevelExpressionWithRhs(parent, n);
1645 :     }
1646 :   }"

"1652 :   private void replaceTopLevelExpressionWithRhs(Node parent, Node n) {
1653 :     // validate inputs
1654 :     switch (parent.getType()) {
1655 :       case Token.BLOCK:
1656 :       case Token.SCRIPT:
1657 :       case Token.FOR:
1658 :       case Token.LABEL:
1659 :         break;
1660 :       default:
1661 :         throw new IllegalArgumentException(
1662 :             "Unsupported parent node type in replaceWithRhs " +
1663 :             Token.name(parent.getType()));
1664 :     }
1665 : 
1666 :     switch (n.getType()) {
1667 :       case Token.EXPR_RESULT:
1668 :       case Token.FUNCTION:
1669 :       case Token.VAR:
1670 :         break;
1671 :       case Token.ASSIGN:
1672 :         Preconditions.checkArgument(parent.isFor(),
1673 :             "Unsupported assignment in replaceWithRhs. parent: %s", Token.name(parent.getType()));
1674 :         break;
1675 :       default:
1676 :         throw new IllegalArgumentException(
1677 :             "Unsupported node type in replaceWithRhs " +
1678 :             Token.name(n.getType()));
1679 :     }
1680 : 
1681 :     // gather replacements
1682 :     List<Node> replacements = Lists.newArrayList();
1683 :     for (Node rhs : getRhsSubexpressions(n)) {
1684 :       replacements.addAll(getSideEffectNodes(rhs));
1685 :     }
1686 : 
1687 :     if (parent.isFor()) {
1688 :       // tweak replacements array s.t. it is a single expression node.
1689 :       if (replacements.isEmpty()) {
1690 :         replacements.add(IR.empty());
1691 :       } else {
1692 :         Node expr = collapseReplacements(replacements);
1693 :         replacements.clear();
1694 :         replacements.add(expr);
1695 :       }
1696 :     }
1697 : 
1698 :     changeProxy.replaceWith(parent, n, replacements);
1699 :   }"

"1766 :   private List<Node> getRhsSubexpressions(Node n) {
1767 :     switch (n.getType()) {
1768 :       case Token.EXPR_RESULT:
1769 :         // process body
1770 :         return getRhsSubexpressions(n.getFirstChild());
1771 :       case Token.FUNCTION:
1772 :         // function nodes have no rhs
1773 :         return Collections.emptyList();
1774 :       case Token.NAME:
1775 :         {
1776 :           // parent is a var node.  rhs is first child
1777 :           Node rhs = n.getFirstChild();
1778 :           if (rhs != null) {
1779 :             return Lists.newArrayList(rhs);
1780 :           } else {
1781 :             return Collections.emptyList();
1782 :           }
1783 :         }
1784 :       case Token.ASSIGN:
1785 :         {
1786 :           // add lhs and rhs expressions - lhs may be a complex expression
1787 :           Node lhs = n.getFirstChild();
1788 :           Node rhs = lhs.getNext();
1789 :           return Lists.newArrayList(lhs, rhs);
1790 :         }
1791 :       case Token.VAR:
1792 :         {
1793 :           // recurse on all children
1794 :           List<Node> nodes = Lists.newArrayList();
1795 :           for (Node child : n.children()) {
